-- Изделия (Москва) — все заявки клиентов
-- Таблица: shipments (city='moscow', source='client'), экспорт от 2026-08-06

CREATE TABLE IF NOT EXISTS shipments_moscow_izdeliya (
    id integer PRIMARY KEY,
    tracking_number varchar(100) NOT NULL,
    customer_name varchar(255) NOT NULL,
    customer_phone varchar(20) NOT NULL,
    delivered_at date NOT NULL,
    return_at date NOT NULL,
    status varchar(20) NOT NULL,
    issued_at timestamp,
    created_at timestamp NOT NULL,
    customer_email varchar(255),
    photo_url text,
    source varchar(20) NOT NULL,
    ready_at timestamp,
    archived_at timestamp,
    visit_number integer NOT NULL DEFAULT 1,
    requires_painting boolean NOT NULL DEFAULT false,
    confirmed_at timestamp,
    visit_date date,
    city varchar(20) NOT NULL
);

